async function main() {
  const client = createClient();
  const batch = [
    {
      sku: "A-1",
      name: "Widget",
      price_cents: 100,
      stock: 3,
      category: "tools",
      tags: ["metal", "sale"],
    },
    {
      sku: "A-2",
      name: "Gadget",
      price_cents: 250,
      stock: 0,
      category: "tools",
    },
    {
      sku: "A-3",
      name: "Thing",
      price_cents: 50,
      stock: 100000,
      category: "books",
      tags: ["sale"],
    },
  ];

  // Query 1: read existing products for batch SKUs
  const q1 = `with
    batch := <json>$batch,
    skus := (for r in json_array_unpack(batch) union (<str>json_get(r, 'sku'))),
    p := (select Product filter .sku in {skus})
  select p {
    sku,
    name,
    price_cents,
    stock,
    category_name := .category.name,
    tag_labels := array_agg(.tags.label order by .tags.label) ?? <array<str>>[],
  }`;
  console.log("Q1 (existing):", JSON.stringify(await client.query(q1, { batch }), null, 2));

  // Query 2: upsert categories
  const q2 = `with
    batch := <json>$batch,
    names := distinct (for r in json_array_unpack(batch) union (<str>json_get(r, 'category')))
  for n in {names} union (
    insert Category { name := n } unless conflict on .name else (select Category filter .name = n)
  )`;
  await client.execute(q2, { batch });
  console.log("Cats:", JSON.stringify(await client.query("select Category.name order by .name")));

  // Query 3: upsert tags
  const q3 = `with
    batch := <json>$batch,
    labels := distinct (
      for r in json_array_unpack(batch) union (
        array_unpack(<array<str>>json_get(r, 'tags')) ?? {}
      )
    )
  for l in {labels} union (
    insert Tag { label := l } unless conflict on .label else (select Tag filter .label = l)
  )`;
  await client.execute(q3, { batch });
  console.log("Tags:", JSON.stringify(await client.query("select Tag.label order by .label")));

  // Query 4: insert new products
  const q4 = `with
    batch := <json>$batch,
    rec := for r in json_array_unpack(batch) union (
      select {
        sku := <str>json_get(r, 'sku'),
        name := <str>json_get(r, 'name'),
        price_cents := <int64>json_get(r, 'price_cents'),
        stock := <int64>json_get(r, 'stock'),
        category_name := <str>json_get(r, 'category'),
        tag_names := <array<str>>json_get(r, 'tags'),
      }
    ),
    existing_skus := (select Product filter .sku in {rec.sku}).sku
  for r in {rec} filter r.sku not in {existing_skus} union (
    insert Product {
      sku := r.sku,
      name := r.name,
      price_cents := r.price_cents,
      stock := r.stock,
      category := (select Category filter .name = r.category_name limit 1),
      tags := (select Tag filter .label in {array_unpack(r.tag_names) ?? {}}),
    }
  )`;
  const ins = await client.query(q4, { batch });
  console.log("Inserted:", JSON.stringify(ins, null, 2));

  // Query 5: update changed products (with differs check)
  const q5 = `with
    batch := <json>$batch,
    rec := for r in json_array_unpack(batch) union (
      select {
        sku := <str>json_get(r, 'sku'),
        name := <str>json_get(r, 'name'),
        price_cents := <int64>json_get(r, 'price_cents'),
        stock := <int64>json_get(r, 'stock'),
        category_name := <str>json_get(r, 'category'),
        tag_names := <array<str>>json_get(r, 'tags'),
      }
    ),
    existing := (select Product filter .sku in {rec.sku})
  for r in {rec} filter exists (
    select existing filter .sku = r.sku and (
      .name != r.name or
      .price_cents != r.price_cents or
      .stock != r.stock or
      .category.name != r.category_name or
      exists (.tags.label except (array_unpack(r.tag_names) ?? {})) or
      exists ((array_unpack(r.tag_names) ?? {}) except .tags.label)
    )
  ) union (
    update Product filter .sku = r.sku set {
      name := r.name,
      price_cents := r.price_cents,
      stock := r.stock,
      category := (select Category filter .name = r.category_name limit 1),
      tags := (select Tag filter .label in {array_unpack(r.tag_names) ?? {}}),
    }
  )`;
  const upd = await client.query(q5, { batch });
  console.log("Updated:", JSON.stringify(upd, null, 2));

  // Verify final state
  const finalState = `select Product {
    sku, name, price_cents, stock,
    category_name := .category.name,
    tag_labels := array_agg(.tags.label order by .tags.label) ?? <array<str>>[],
  } order by .sku`;
  console.log("Final:", JSON.stringify(await client.query(finalState), null, 2));

  await client.close();
}

main().catch((e) => {
  console.error("ERR", e);
  process.exit(1);
});

